const r=await Promise.allSettled([
tools.exec_command({cmd:"rg -n -C 4 \"H1|H2|H3|H4|H5|H6|random.effects|60%|0.60|sign|group size\" prereg/preregistration.md",max_output_tokens:6500}),
tools.exec_command({cmd:"python -c 'import pandas as pd; d=pd.read_csv(\"analysis/output/sim_delta.csv\"); x=d.pivot(index=[\"tau\",\"phi\",\"gamma\",\"omega\"],columns=\"m\",values=\"acc_ew\"); y=d.pivot(index=[\"tau\",\"phi\",\"gamma\",\"omega\"],columns=\"m\",values=\"delta\"); print(\"EW m3 mean\",x[3].mean(),\"m4 mean\",x[4].mean(),\"m5 mean\",x[5].mean()); print(\"EW m4<m3 cells\",(x[4]<x[3]).sum(),\"of\",len(x)); print(\"CW m4<m3 cells\",(d.pivot(index=[\"tau\",\"phi\",\"gamma\",\"omega\"],columns=\"m\",values=\"acc_cw\")[4]<d.pivot(index=[\"tau\",\"phi\",\"gamma\",\"omega\"],columns=\"m\",values=\"acc_cw\")[3]).sum()); print(\"delta m4-m3 negative beyond .002\",((y[4]-y[3])<-.002).sum()); print(\"delta m5-m4 negative beyond .002\",((y[5]-y[4])<-.002).sum())'",max_output_tokens:2500}),
tools.exec_command({cmd:"rg -n \"supported|H1|H3|arbitrat|direction|random-effects|meta-analy\" manuscript/manuscript.md deviations.md",max_output_tokens:4800}),
tools.exec_command({cmd:"rg -n \"H1|H2|H3|H5|H6|sign|brier|m=4|omega|repetitions\" analysis/scripts/figures.py analysis/scripts/*.py -g '!empirical.py' -g '!simulate.py' -g '!h6.py'",max_output_tokens:2000})
]);r.forEach((x,i)=>text(JSON.stringify({i,status:x.status,result:x.status==="fulfilled"?x.value:x.reason})));

const r=await Promise.allSettled([
tools.exec_command({cmd:"python -c 'import pandas as pd,numpy as np; d=pd.read_csv(\"analysis/output/sim_delta.csv\").sort_values([\"tau\",\"phi\",\"gamma\",\"omega\",\"m\"]); k=[\"tau\",\"phi\",\"gamma\",\"omega\"]; q=d.groupby(k); a=q[\"delta\"].diff(); prev=q[\"m\"].shift(); x=d.assign(drop=a,prev=prev); v=x[x[\"drop\"]<-.002]; print(\"H2 violations total\",len(v)); print(\"by transition\",v.groupby([\"prev\",\"m\"]).size().to_dict()); print(\"without m4 adjacency\",len(v[(v.prev!=4)&(v.m!=4)])); print(\"interior lambda all\",d[(d.lam_star>0)&(d.lam_star<1)].groupby(k).ngroups); print(\"interior lambda excluding m4\",d[(d.m!=4)&(d.lam_star>0)&(d.lam_star<1)].groupby(k).ngroups)'",max_output_tokens:2500}),
tools.exec_command({cmd:"python -c 'import pandas as pd,numpy as np; d=pd.read_csv(\"analysis/output/sim_delta.csv\"); s=pd.read_csv(\"analysis/output/sim_cells.csv\"); k=[\"tau\",\"phi\",\"gamma\",\"omega\"]; dm=d.groupby(k).delta.mean().reset_index(name=\"calc\"); x=s.merge(dm,on=k); print(\"cell mean delta discrepancy\",(x.mean_delta-x.calc).abs().max()); print(\"sign mean positive\",(s.mean_delta>0).sum(),\"negative\",(s.mean_delta<0).sum()); print(\"m4 mean delta\",d[d.m==4].delta.mean(),\"non-m4 mean delta\",d[d.m!=4].delta.mean())'",max_output_tokens:1800}),
tools.exec_command({cmd:"nl -ba prereg/preregistration.md | sed -n '69,79p;90,119p'",max_output_tokens:4000}),
tools.exec_command({cmd:"rg -n \"only when|only for|point.*same way|opposite|arbitrat|non.monotone|interior|majority\" manuscript/manuscript.md",max_output_tokens:3500})
]);r.forEach((x,i)=>text(JSON.stringify({i,status:x.status,result:x.status==="fulfilled"?x.value:x.reason})));

