tools.exec_command({cmd:"python -c 'import pandas as pd; d=pd.read_csv(\"analysis/output/sim_delta.csv\"); k=[\"tau\",\"phi\",\"gamma\",\"omega\"]; a=d.groupby(k).delta.mean(); b=d[d.m!=4].groupby(k).delta.mean(); print(\"mean_delta cell signs with m4\",int((a>0).sum()),int((a<0).sum())); print(\"without m4\",int((b>0).sum()),int((b<0).sum())); print(\"sign changes\",int(((a>0)!=(b>0)).sum())); print(\"m4 average gain\",d[d.m==4].delta.mean()); print(\"non4 average gain\",d[d.m!=4].delta.mean())'",max_output_tokens:1000}),
tools.exec_command({cmd:"python -c 'import pandas as pd; x=pd.read_csv(\"analysis/output/empirical_datasets.csv\"); x=x[x.included==True]; print(\"included\",len(x),\"m7 missing\",x.brier_improvement_m7.isna().sum()); print(\"mmax below 7\",(x.m_max<7).sum()); print(\"sign count\",(x.mean_delta>0).sum(),(x.mean_delta<0).sum(),(x.mean_delta==0).sum()); print(\"rho negative\",(x.icc_rho<0).sum())'",max_output_tokens:1000})
]);r.forEach((x,i)=>text(JSON.stringify({i,status:x.status,result:x.status==="fulfilled"?x.value:x.reason})));
